 pub fn json_artifact_sha256<T: Serialize>(
     artifact: &T,
 ) -> Result<String, BoltV3OperatorArtifactError> {
     let bytes =
         serde_json::to_vec_pretty(artifact).map_err(BoltV3OperatorArtifactError::Serialize)?;
     Ok(sha256_hex(&bytes))

